// インシデントデータを処理し、テンプレートに適した構造を作成
const incidents = $input.all();

if (incidents.length === 0) {
    // インシデントなし
    return {
        json: {
            total_incidents: 0,
            critical_count: 0,
            high_count: 0,
            medium_count: 0,
            low_count: 0,
            incidents: [],
            incident_rows: "",
            email_manager: $json.email_manager,
            name_manager: $json.name_manager
        }
    };
}

// インシデントあり - 最初のインシデントからデータを取得（すべて同じ統計を持つ）
const firstIncident = $input.first().json;

// テーブル用のHTML行を作成
const rows = incidents.map(item => {
  const incident = item.json;
  const severity = incident.severity || "unknown";

  // 重要度の日本語翻訳
  const severityMap = {
    'critical': '重大',
    'high': '高',
    'medium': '中',
    'low': '低'
  };

  const severityText = severityMap[severity] || severity.toUpperCase();

  return `
<tr style="${severity === 'critical' ? 'background-color: #fdf2f2;' : ''}">
    <td><strong>#${incident.id || ''}</strong></td>
    <td>${incident.title || ''} ${severity === 'critical' ? '<span class="urgent-badge">緊急</span>' : ''}</td>
    <td>${incident.location || '未確定'}</td>
    <td><span class="severity-${severity}">${severityText}</span></td>
    <td>${incident.occurred_at ? new Date(incident.occurred_at).toLocaleDateString('ja-JP') : ''}</td>
    <td>${incident.created_at ? new Date(incident.created_at).toLocaleDateString('ja-JP') : ''}</td>
</tr>`;
}).join('');

return {
    json: {
        total_incidents: firstIncident.total_incidents,
        critical_count: firstIncident.critical_count,
        high_count: firstIncident.high_count,
        medium_count: firstIncident.medium_count,
        low_count: firstIncident.low_count,
        incidents: incidents,
        incident_rows: rows,
        email_manager: firstIncident.email_manager,
        name_manager: firstIncident.name_manager
    }
};
